    if (array == null) {
        return 0;
    }
    int hash = 193;
    long transientValue = 0;
    for (byte b : array) {
        transientValue = (int)(b * hash);
        hash = 29 * hash + transientValue;
    }
    return hash ^ (int)(hash >> 32);
}

