    }
    for (int i = numVertices / 2; i < numVertices; i++) {
        part2.add(new V("Part2_" + i));
    }

    // Destroy all edges from the target graph and add edges between partitions
    target.removeEdgesFromGraph();
    for (V vertex : part1) {
        for (V edgeVertex : part2) {
