public class ReflectionUtil {

    public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
        if (!(genericType instanceof ParameterizedType)) {
            return null;
        }

        Type[] actualTypeArguments = ((ParameterizedType) genericType).getActualTypeArguments();
        if (actualTypeArguments.length == 0) {
            return genericType getClassTypeArguments(targetType);
        }

        Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
        for (int i = 0; i < actualTypeArguments.length; i++) {
            resolvedArguments[i] = targetType.isArray() ?
                resolveArrayArgument(actualTypeArguments[i], targetType.getComponentType()) :
                resolvePrimitiveArgument(actualTypeArguments[i], targetType);
        }

        return resolvedArguments;
    }

    private static Class<?>[] genericTypegetClassTypeArguments(Class<?> clazz) {
        if (clazz.isArray()) {
            return new Class<?>[] { clazz.getComponentType() };
        } else if (clazz.isPrimitive()) {
            return new Class<?>[] { clazz };
        } else {
            return clazz.getTypeParameters();
        }
    }

    private static Class<?> resolveArrayArgument(Type type, Class<?> componentType) {
        if (type instanceof ParameterizedType) {
            Type[] genericTypeArguments = ((ParameterizedType) type).getActualTypeArguments();
            return getComponentType(genericTypeArguments);
        }
        return componentType;
    }

    private static Class<?> resolvePrimitiveArgument(Type type, Class<?> componentType) {
