        List<Map<String, Object>> diffMappings = new ArrayList<>();

        for (Map<String, Object> currentMapping : currentMappings.getMappings()) {
            if (!mappings.contains(currentMapping)) {
                if (!tableName.equals("_source")) {
                    diffMappings.add(currentMapping);
                }
            } else {
                Map<String, Object> existingMapping = mappings.stream()
                        .filter(m -> m.equals(currentMapping))
                        .findFirst()
                        .orElse(null);

                for (Map.Entry<String, Object> entry : currentMapping.entrySet()) {
                    if (!existingMapping.containsKey(entry.getKey())) {
                        diffMappings.add(existingMapping);
                    }
                }
            }
        }

        return new Mappings(diffMappings);
    }

    public List<Map<String, Object>> getMappings() {
