public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || len < 0) {
        throw new IllegalArgumentException("Bad input"); //$NON-NLS-1$
    }

    int size = 0;
    int charLength = 0;

    for (int i = index; i < index + len; i++) {
        char charValue = str.charAt(i);
        if (charValue <= 0x7F) { // 1-byte character
            charLength += 1;
        } else if (charValue <= 0x7FF) { // 2-byte character
            charLength += 2;
            size += 1;
        } else if (charValue <= 0xFFFF) { // 3-byte character
            charLength += 3;
            size += 1;
        } else if (charValue <= 0x10FFFF) { // 4-byte character
            charLength += 4;
            size += 1;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 character at index " + i); //$NON-NLS-1$
        }
        if (charLength > 0) {
            size += 4; // Add 4 for padding
        }
    }

    return size > 0 ? size : 4; // Add 4 for alignment if needed
}

