    public ByteVector() {
        this(new byte[0], 0);
    }

    public ByteVector(final byte[] data, final int length) {
        this.data = data;
        this.length = length;
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteArrayValue == null) {
            byteArrayValue = new byte[byteLength];
        }

        if (byteOffset + byteLength > this.data.length) {
            enlarge(byteLength);
        }

        byte[] newData = Arrays.copyOf(this.data, this.data.length + byteLength);
        System.arraycopy(byteArrayValue, byteOffset, newData, this.data.length, byteLength);
        this.data = newData;
        this.length += byteLength;
        return this;
    }

    private void enlarge(final int amount) {
        int newLength = this.data.length + amount;
        byte[] newData = Arrays.copyOf(this.data, newLength);
        this.data = newData;
    }

    public byte[] getData() {
