public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        throw new IllegalArgumentException("Capacity must be at least 2");
    }

    int offset = desiredCapacity >= 1000 ? (int) (desiredCapacity * 0.11) : 2;
    int capacity = desiredCapacity + offset;

    while (!isPrime(capacity)) {
        capacity++;
    }

    return capacity;
}

private static boolean isPrime(int num) {
    if (num <= 1) {
        return false;
    }
    if (num <= 3) {
        return true;
    }
    if (num % 2 == 0 || num % 3 == 0) {
        return false;
    }
    int i = 5;
    while (i * i <= num) {
        if (num % i == 0 || num % (i + 2) == 0) {
            return false;
        }
        i += 6;
    }
    return true;
}

