public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    boolean escapeNext = false;

    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);

        if (escapeNext) {
            result.append(ch);
            escapeNext = false;
            continue;
        }

        if (ch == '\\') {
            escapeNext = true;
            continue;
        }

        result.append(ch);
    }

    return result.toString();
}

