    Circulator<Optional<Node>> circ = new IndexCirculator<>(Map.ofStop(stop), start);
    while (true) {
        Node node = circ.getLeft();
        if (node == null) {
            return null; // Return null if no node is found
        }
        if (predicate.test(node)) {
            return circ; // Return the circulator to the node satisfying the predicate
        }
        circ.index = (circ.index + dir) % circ.stop.index; // Move in the specified direction
    }
}

