public GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    GraphPath<V,E> path = new GraphPath<>();
    Node<V> current = null, prev = null;

    for (E edge : tour) {
        path.add(edge.source(), edge.destination());
        current = graph.getNode(toId(edge.source()));
        prev = graph.getNode(toId(edge.destination()));
        // If current node doesn't have an outgoing link to prev node, treat it as a new path (edge without prev node)
        if (!current.linksTo(prev)) {
            path.start();
            path.add(prev);
        } else {
            path.add(current);
        }
    }

    path.end();
    return path;
}

