public void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (minLabel <= 0) {
        // Clear the out-of-the-buckets list
        bucketsByLabel.get(0).addAll(labels);
        for (int i = 1; i < bucketsByLabel.size(); i++) {
            bucketsByLabel.set(i, new HashSet<>());
        }
    } else {
        // Clear the out-of-the-buckets list
        bucketsByLabel.get(minLabel - 1).addAll(labels);
        for (int i = minLabel; i < bucketsByLabel.size(); i++) {
            bucketsByLabel.set(i, new HashSet<>());
        }
        // Move vertices from minLabel-1 to 0 bucket
        for (int i = 0; i < bucketsByLabel.size(); i++) {
            bucketsByLabel.get(i).addAll(bucketsByLabel.get(minLabel - 1));
            bucketsByLabel.get(minLabel - 1).clear();
        }
    }
}

