public String parseToken(final char[] terminators) {
    int pos = 0; // Position of the current character in the input array
    StringBuilder token = new StringBuilder(); // StringBuilder to dynamically construct the token

    while (pos < terminators.length) {
        char c = terminators[pos];
        if (token.length() > 0 || pos == 0) {
            token.append(c);
        }
        pos++;
    }

    return token.toString();
}

