public static boolean startsWith(final String str,final String prefix,final boolean ignoreCase){
    if(str == null && prefix == null) return true;
    if(str == null || prefix == null) return false;
    int len = str.length();
    int m = prefix.length();
    if (m > len) return false;

    for(int i = 0; i < m; i++) {
        char ch1 = str.charAt(i);
        char ch2 = prefix.charAt(i);
        if(!ignoreCase && ch1 != ch2) return false;
        if(ignoreCase && Character.toLowerCase(ch1) != Character.toLowerCase(ch2)) return false;
    }

    return true;
}

