public static String applyRelativePath(String path, String relativePath) {
    String[] parts = relativePath.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        if (part.startsWith("../") || part.startsWith("./")) {
            path = legalizePath(path, part);
        } else {
            path = path + "/" + part;
        }
    }
    return path;
}

private static String legalizePath(String path, String relPath) {
    int start = path.lastIndexOf('/');
    int length = relPath.length();
    if (start != -1 && (length == 2 && ".."".equals(relPath) || length == 3 && "./".equals(relPath))) {
        return path.substring(0, start);
    } else if (length == 1 && relPath.equals("..")) {
        if (path.startsWith("/") || path.startsWith("\\\\")) {
            return "";
        }
        int n = path.lastIndexOf("\\\\");
        if (n == -1) {
            return path.substring(0, path.lastIndexOf '/');
        } else {
            return path.substring(0, n);
        }
    }
    return path;
}

