protected void append(LoggingEvent event) {
    AtomicReference<Set<SocketChannel>> channels = new AtomicReference<>(null);
    SocketChannel ch = null;
    for (;;) {
        ch = channels.get();
        if (ch != null) {
            try {
                ch.write(ByteBuffer.wrap(Charset.forName("UTF-8").encode(SLF4J_PLACEHOLDER + event.getMessage())));
                break;
            } catch (IOException ioe) {
                channels.clear();
            }
        }
        try {
            Selector sel = Selector.open();
            ch.register(sel, SelectionKey.OP_WRITE);
            if (!sel.selectNow()>0)
                continue;

            channels.clear();
            selectableChannelIterator chIterator = sel.selectedKeys().iterator();
            while (chIterator.hasNext()) {
                SelectionKey key = (SelectionKey) chIterator.next();
                if (!key.isValid())
                    continue;

                if (key.isReadable()) {
                    byte[] buffer = new byte[1024];
                    int bytesRead;
                    InputStream is = key.channel().socket().getInputStream();
                    while ((bytesRead = is.read(buffer)) != -1) {
                        channels.get().write(ByteBuffer.wrap(buffer, 0, bytesRead));
                    }
                    is.close();
                }

                if (key.isWritable()) {
                    ch.write(ByteBuffer.wrap(Charset.forName("UTF-8").encode(SLF4J_PLACEHOLDER + event.getMessage())));
                    key.interestOps(key.interestOps() ^ SelectionKey.OP_WRITE);
                }
            }
            chIterator.close();
        } catch (InterruptedException ie) {
            System.out.println("Thread was interrupted.");
            break;
        } catch (IOException ioe) {
            System.out.println("Failed to connect. " + ioe.getMessage());
        }
    }
}

